"use client";
/* Scene, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Scene(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("scene"); }, []);
  return React.createElement("piix-scene", piixAttrs(props));
}

export default Scene;
